// ================== НАСТРОЙКИ ==================
// Держи этот блок одинаковым в обоих workflow (проверка и бронь).
const CONFIG = {
  timezone: 'Europe/Kiev', // так этот пояс называет сам Google (ctz=Europe/Kiev в ссылках календарей)
  durationMinutes: 120,   // сколько длится одна бронь
  openTime: '10:00',      // самая ранняя бронь
  closeTime: '23:00',     // бронь должна закончиться не позже этого времени
  minLeadMinutes: 30,     // за сколько минут минимум можно бронировать
  slotStepMinutes: 30,    // шаг, с которым ищем другое свободное время
  maxGuestsPerTable: 4,   // больше гостей -> к администратору (0 = не проверять)
  // ID календаря: Google Календарь -> Настройки -> календарь столика -> «Интеграция календаря» -> Идентификатор календаря
