    { id: 'table_5', name: 'Столик 5', calendarId: 'c64fd8c99abf438c7e5c601099916d4639af4e349c2447f4d3714a6f9131d002@group.calendar.google.com' },
    { id: 'table_6', name: 'Столик 6', calendarId: 'cdcf036866c9279f7a53814c00c39dc26f64377597b4141af30a5be730db8f6e@group.calendar.google.com' },
    { id: 'table_7', name: 'Столик 7', calendarId: 'e0c91081234b7032769c99349a8f1340f790353c7bdc9b32c9b1154f5531829a@group.calendar.google.com' },
    { id: 'table_8', name: 'Столик 8', calendarId: 'e093c709d1cd09a3d6f4e0b1f68df236662a3628ea98c7fea0ae8ee3b43ce249@group.calendar.google.com' },
