    { id: 'table_20', name: 'Столик 20', calendarId: 'e56ba7258ec30bd7d4d956e538c71e329cda1dbe91e36113d47bd64535d0b9e7@group.calendar.google.com' },
    { id: 'table_21', name: 'Столик 21', calendarId: '05987ddf5ff1b0faa7fbe74f90250333920eb8f9e844e8888ec84f42295053f7@group.calendar.google.com' },
    { id: 'table_22', name: 'Столик 22', calendarId: '03c1808e6fb883fa01dacf2113ca5739ba9e95c7df0854c47f8050fa447858e6@group.calendar.google.com' },
    { id: 'table_23', name: 'Столик 23', calendarId: '646c663c6745119dbbc6e65640bd755a4130051354f76a7ebf05df4d89062c3f@group.calendar.google.com' },
    { id: 'table_24', name: 'Столик 24', calendarId: 'd604c6b73281ab9c886ab1b3a0097625f0af5be5dcf334d159c9f1ce5554c28d@group.calendar.google.com' },
  ],
};
// ================================================

const MODE = 'book'; // 'check' или 'book', не менять

const WEEKDAYS = ['понеділок', 'вівторок', 'середа', 'четвер', "п'ятниця", 'субота', 'неділя'];
const MONTHS = ['січня', 'лютого', 'березня', 'квітня', 'травня', 'червня', 'липня', 'серпня', 'вересня', 'жовтня', 'листопада', 'грудня'];

const raw = $input.first().json;
const b = { ...(raw.query || {}), ...(raw.body || {}) };

// Принимаем разные названия полей из тулов ElevenLabs: name / customer_name, table_id / table_number и т.п.
const field = (...keys) => {
  for (const k of keys) {
    const v = b[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return undefined;
};
const IN = {
  date: field('date', 'booking_date', 'day'),
  time: field('time', 'booking_time', 'hour'),
  guests: field('guests', 'guests_count', 'number_of_guests', 'people', 'persons', 'party_size'),
  name: field('name', 'customer_name', 'client_name', 'guest_name', 'full_name'),
  phone: field('phone', 'phone_number', 'customer_phone', 'tel'),
  comment: field('comment', 'notes', 'note', 'wishes', 'special_requests'),
  table: field('table_id', 'table_number', 'table', 'table_name'),
};
const receivedFields = 'Отримані поля: ' + (Object.keys(b).join(', ') || 'жодного');

// Столик можно передать как table_4, 4 или «Столик 4»
function normTable(v) {
  if (v === undefined) return null;
  const s = String(v).trim();
  const exact = CONFIG.tables.find((t) => t.id === s || t.name.toLowerCase() === s.toLowerCase());
  if (exact) return exact.id;
  const m = s.match(/(\d+)/);
  if (m) {
    const byNum = CONFIG.tables.find((t) => t.id === 'table_' + m[1]);
    if (byNum) return byNum.id;
  }
  return null;
}
const zone = CONFIG.timezone;
const now = DateTime.now().setZone(zone);

const fail = (message, extra = {}) => [{
  json: { ok: false, ...(MODE === 'book' ? { booked: false } : { available: false }), message, ...extra },
}];

function parseDate(v) {
  const s = String(v ?? '').trim().toLowerCase();
  if (['сьогодні', 'сегодня', 'today'].includes(s)) return now.startOf('day');
  if (['завтра', 'tomorrow'].includes(s)) return now.plus({ days: 1 }).startOf('day');
  if (['післязавтра', 'послезавтра'].includes(s)) return now.plus({ days: 2 }).startOf('day');
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] }, { zone });
  m = s.match(/^(\d{1,2})[.\/](\d{1,2})(?:[.\/](\d{2,4}))?$/);
  if (m) {
    let year = m[3] ? +m[3] : now.year;
    if (year < 100) year += 2000;
    let d = DateTime.fromObject({ year, month: +m[2], day: +m[1] }, { zone });
    if (!m[3] && d.isValid && d < now.startOf('day')) d = d.plus({ years: 1 });
    return d;
  }
  return null;
}

function parseTime(v) {
  const m = String(v ?? '').trim().match(/^(\d{1,2})(?:[:.](\d{2}))?$/);
  if (!m) return null;
  const hour = +m[1];
  const minute = +(m[2] || 0);
  if (hour > 23 || minute > 59) return null;
  return { hour, minute };
}

const day = parseDate(IN.date);
if (!day || !day.isValid) {
  return fail('Не вдалося розпізнати дату. Уточніть дату й передайте її у форматі YYYY-MM-DD.', { debug_for_admin: receivedFields });
}
const t = parseTime(IN.time);
if (!t) {
  return fail('Не вдалося розпізнати час. Уточніть час і передайте його у форматі HH:mm.', { debug_for_admin: receivedFields });
}

let guests = null;
if (IN.guests !== undefined) {
  guests = parseInt(IN.guests, 10);
  if (isNaN(guests) || guests < 1) return fail('Уточніть кількість гостей.');
}
if (guests && CONFIG.maxGuestsPerTable && guests > CONFIG.maxGuestsPerTable) {
  return fail(
    `Онлайн-бронь доступна для компаній до ${CONFIG.maxGuestsPerTable} гостей. Для більшої компанії запропонуйте передати контакт адміністратору.`,
    { needs_admin: true },
  );
}

const start = day.set({ hour: t.hour, minute: t.minute, second: 0, millisecond: 0 });
const end = start.plus({ minutes: CONFIG.durationMinutes });
const [oh, om] = CONFIG.openTime.split(':').map(Number);
const [ch, cm] = CONFIG.closeTime.split(':').map(Number);
const open = day.set({ hour: oh, minute: om, second: 0, millisecond: 0 });
let close = day.set({ hour: ch, minute: cm, second: 0, millisecond: 0 });
if (close <= open) close = close.plus({ days: 1 });

if (start < now.plus({ minutes: CONFIG.minLeadMinutes })) {
  return fail(`Цей час уже минув або до нього менше ${CONFIG.minLeadMinutes} хвилин. Запропонуйте інший час.`);
}
if (start < open || end > close) {
  return fail(
    `Бронь можлива з ${CONFIG.openTime}, і вона має закінчитися до ${CONFIG.closeTime}. Одна бронь триває ${CONFIG.durationMinutes / 60} год. Запропонуйте інший час.`,
  );
}

let name = null;
let phone = null;
let comment = null;
if (MODE === 'book') {
  name = String(IN.name ?? '').trim();
  phone = String(IN.phone ?? '').trim();
  comment = String(IN.comment ?? '').trim() || null;
  if (!name) {
    return fail("Потрібне ім'я гостя. Запитайте ім'я і повторіть бронювання.", { debug_for_admin: receivedFields });
  }
  if (phone.replace(/\D/g, '').length < 9) {
    return fail('Потрібен номер телефону гостя. Запитайте номер і повторіть бронювання.', { debug_for_admin: receivedFields });
  }
}

const dateText = `${WEEKDAYS[start.weekday - 1]}, ${start.day} ${MONTHS[start.month - 1]}`;

return [{
  json: {
    ok: true,
    date: start.toFormat('yyyy-MM-dd'),
    time: start.toFormat('HH:mm'),
    end_time: end.toFormat('HH:mm'),
    date_text: dateText,
    start: start.toISO(),
    end: end.toISO(),
    open: open.toISO(),
    close: close.toISO(),
    guests,
    name,
    phone,
    comment,
    table_id: normTable(IN.table),
    config: CONFIG,
  },
}];

// Столики-кандидаты, по одному элементу на столик.
// Если агент передал table_id из проверки — этот столик пробуем первым.
const req = $input.first().json;
const tables = [...req.config.tables];
if (req.table_id) {
  tables.sort((a, b) => (b.id === req.table_id) - (a.id === req.table_id));
}
return tables.map((t) => ({
  json: {
    id: t.id,
    name: t.name,
    calendarId: t.calendarId,
    start: req.start,
    end: req.end,
  },
}));

// Берём первый свободный столик. Занятость проверяется ещё раз прямо перед бронью,
// чтобы не посадить двух гостей за один столик.
const req = $('Разбор запроса').first().json;
const cands = $('Кандидаты').all().map((i) => i.json);
const res = $input.all().map((i) => i.json);

let pick = null;
const errs = {};
let errors = 0;
cands.forEach((c, i) => {
  const r = res[i] || {};
  if (r.error !== undefined || typeof r.available !== 'boolean') {
    errors++;
    const k = String(r.error ? (typeof r.error === 'string' ? r.error : JSON.stringify(r.error)) : 'пустой ответ Google').slice(0, 200);
    errs[k] = (errs[k] || 0) + 1;
    return;
  }
  if (!pick && r.available) pick = c;
});

if (!pick) {
  if (errors === cands.length) {
    return [{
      json: {
        ok: false,
        found: false,
        booked: false,
        technical_error: true,
        message: 'Технічна помилка: не вдалося перевірити календар. Вибачтеся й запропонуйте передати контакт адміністратору.',
        debug_for_admin: Object.entries(errs).map(([e, c]) => `${e} (${c} календ.)`).join('; '),
      },
    }];
  }
  return [{
    json: {
      ok: true,
      found: false,
      booked: false,
      message: `На ${req.time} (${req.date_text}) вільних столиків уже немає. Перевірте інший час інструментом check_tables.`,
    },
  }];
}

const lines = [
  `Телефон: ${req.phone}`,
  req.guests ? `Гостей: ${req.guests}` : null,
  req.comment ? `Коментар: ${req.comment}` : null,
  'Створено голосовим агентом',
].filter(Boolean);

return [{
  json: {
    found: true,
    calendarId: pick.calendarId,
    table_id: pick.id,
    table_name: pick.name,
    start: req.start,
    end: req.end,
    summary: `Бронь: ${req.name}${req.guests ? `, ${req.guests} ос.` : ''}`,
    description: lines.join('\n'),
  },
}];

// Ответ агенту после создания события в календаре столика.
const req = $('Разбор запроса').first().json;
const pick = $('Выбор столика').first().json;
const ev = $input.first().json;

if (ev.error || !ev.id) {
  return [{
    json: {
      ok: false,
      booked: false,
      technical_error: true,
      message: 'Технічна помилка: бронь не збереглася. Вибачтеся й запропонуйте передати контакт адміністратору.',
    },
  }];
}

return [{
  json: {
    ok: true,
    booked: true,
    table_id: pick.table_id,
    table_name: pick.table_name,
    date: req.date,
    date_text: req.date_text,
    time: req.time,
    end_time: req.end_time,
    event_id: ev.id,
    message: `Бронь підтверджено: ${req.date_text}, ${req.time}–${req.end_time}, ${pick.table_name}, на ім'я ${req.name}.`,
  },
}];
